/** @typedef {'low' | 'normal' | 'high' | 'urgent'} Priority */

/**
 * Priority handler for todo items.
 * Encapsulates priority validation, comparison, and sorting logic.
 */
export class PriorityHandler {
  static #WEIGHTS = new Map([
    ['low', 0],
    ['normal', 1],
    ['high', 2],
    ['urgent', 3]
  ]);

  static DEFAULT = 'normal';

  static get ALL() {
    return Array.from(this.#WEIGHTS.keys());
  }

  static isValid(value) {
    return typeof value === 'string' && this.#WEIGHTS.has(value);
  }

  static normalize(value) {
    return this.isValid(value) ? value : this.DEFAULT;
  }

  static compare(a, b) {
    const weightA = this.#WEIGHTS.get(a) ?? 0;
    const weightB = this.#WEIGHTS.get(b) ?? 0;
    return weightB - weightA;
  }

  static sort(todos) {
    return [...todos].sort((a, b) => {
      const aPriority = this.normalize(a.priority);
      const bPriority = this.normalize(b.priority);
      return this.compare(aPriority, bPriority);
    });
  }
}

// Export individual functions for backward compatibility
export const PRIORITIES = PriorityHandler.ALL;
export const DEFAULT_PRIORITY = PriorityHandler.DEFAULT;
export const isPriority = PriorityHandler.isValid.bind(PriorityHandler);
export const toPriority = PriorityHandler.normalize.bind(PriorityHandler);
export const comparePriority = PriorityHandler.compare.bind(PriorityHandler);
export const sortByPriority = PriorityHandler.sort.bind(PriorityHandler);

