  const unsortedTodos = [
    { priority: 'low' },
    { priority: 'urgent' },
    { priority: 'normal' }
  ];
  const sortedTodos = sortByPriority(unsortedTodos);
  assert.deepEqual(sortedTodos.map((t) => t.priority), ['urgent', 'normal', 'low']);
