```javascript
test('sortByPriority treats a missing priority as the default', () => {
  const sorted = sortByPriority([{ priority: 'low' }, {}, { priority: 'urgent' }]);
  assert.equal(sorted[0].priority, 'urgent');
  assert.equal(sorted[1].priority, undefined); // Verify it's actually undefined
  assert.equal(sorted[2].priority, 'low');
  // Also verify the default is used in sorting:
